{"command":"cat > /workspace/src/main.rs <<'RS'
use anyhow::{anyhow, Context};
use clap::{Arg, ArgAction, Command, value_parser};
use ratatui::style::Color;
use std::net::{IpAddr, ToSocketAddrs};
use std::process::Command as ProcCommand;
use std::str::FromStr;
use std::time::Duration;

fn build_cli() -> Command {
    Command::new("gping")
        .about("Ping, but with a graph.")
        .version("1.20.1")
        .long_version("1.20.1\ncommit_hash: 42449c03\nbuild_time: 2026-06-11 22:08:42 +00:00\nbuild_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu")
        .arg(
            Arg::new("HOSTS_OR_COMMANDS")
                .help("Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1")
                .num_args(1..)
        )
        .arg(
            Arg::new("cmd")
                .long("cmd")
                .help("Graph the execution time for a list of commands rather than pinging hosts")
                .action(ArgAction::SetTrue)
                .conflicts_with("ping-args")
        )
        .arg(
            Arg::new("watch-interval")
                .short('n')
                .long("watch-interval")
                .value_name("WATCH_INTERVAL")
                .help("Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5")
                .value_parser(value_parser!(f64))
        )
        .arg(
            Arg::new("buffer")
                .short('b')
                .long("buffer")
                .value_name("BUFFER")
                .help("Determines the number of seconds to display in the graph")
                .value_parser(value_parser!(u64))
                .default_value("30")
        )
        .arg(
            Arg::new("ipv4")
                .short('4')
                .help("Resolve ping targets to IPv4 address")
                .action(ArgAction::SetTrue)
                .conflicts_with("ipv6")
        )
        .arg(
            Arg::new("ipv6")
                .short('6')
                .help("Resolve ping targets to IPv6 address")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("interface")
                .short('i')
                .long("interface")
                .value_name("INTERFACE")
                .help("Interface to use when pinging")
        )
        .arg(
            Arg::new("simple-graphics")
                .short('s')
                .long("simple-graphics")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("vertical-margin")
                .long("vertical-margin")
                .value_name("VERTICAL_MARGIN")
                .help("Vertical margin around the graph (top and bottom)")
                .value_parser(value_parser!(u16))
                .default_value("1")
        )
        .arg(
            Arg::new("horizontal-margin")
                .long("horizontal-margin")
                .value_name("HORIZONTAL_MARGIN")
                .help("Horizontal margin around the graph (left and right)")
                .value_parser(value_parser!(u16))
                .default_value("0")
        )
        .arg(
            Arg::new("color")
                .short('c')
                .long("color")
                .value_name("color")
                .help("Assign color to a graph entry.\n\nThis option can be defined more than once as a comma separated string, and the\norder which the colors are provided will be matched against the hosts or\ncommands passed to gping.\n\nHexadecimal RGB color codes are accepted in the form of '#RRGGBB' or the\nfollowing color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta',\n'cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow',\n'light-blue', 'light-magenta', 'light-cyan', and 'white'")
                .action(ArgAction::Append)
        )
        .arg(
            Arg::new("clear")
                .long("clear")
                .help("Clear the graph from the terminal after closing the program")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("ping-args")
                .long("ping-args")
                .value_name("PING_ARGS")
                .help("Extra arguments to pass to `ping`. These are platform dependent")
                .num_args(0..)
                .allow_hyphen_values(true)
        )
}

fn expand_cloud_host(host: &str) -> String {
    if let Some(region) = host.strip_prefix("aws:") {
        format!("ec2.{}.amazonaws.com", region)
    } else if let Some(region) = host.strip_prefix("gcp:") {
        if region.is_empty() {
            "cloud.google.com".to_string()
        } else {
            format!("storage.{}.rep.googleapis.com", region)
        }
    } else {
        host.to_string()
    }
}

fn main() -> anyhow::Result<()> {
    let matches = build_cli().get_matches();

    let hosts_or_commands: Vec<String> = matches
        .get_many::<String>("HOSTS_OR_COMMANDS")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if hosts_or_commands.is_empty() {
        return Err(anyhow!(
            "At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments."
        ));
    }

    let is_cmd = matches.get_flag("cmd");
    let ipv4 = matches.get_flag("ipv4");
    let ipv6 = matches.get_flag("ipv6");

    // Colors: split by comma, flatten, take first N, validate
    let raw_colors: Vec<String> = matches
        .get_many::<String>("color")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut flat_colors: Vec<String> = Vec::new();
    for c in &raw_colors {
        for part in c.split(',') {
            flat_colors.push(part.to_string());
        }
    }
    // Validate first N
    let n = hosts_or_commands.len();
    for i in 0..std::cmp::min(n, flat_colors.len()) {
        let code = &flat_colors[i];
        Color::from_str(code).with_context(|| format!("Invalid color code: `{}`", code))?;
    }

    // Watch interval
    let watch_interval_opt: Option<f64> = matches.get_one::<f64>("watch-interval").copied();
    let default_interval = if is_cmd { 0.5 } else { 0.2 };
    let interval_secs = watch_interval_opt.unwrap_or(default_interval);
    let interval_duration = Duration::from_millis((interval_secs * 1000.0) as u64);

    if is_cmd {
        // Cmd mode: no ping, go to TUI
        // For now, just try to enable raw mode to match non-tty error
        crossterm::terminal::enable_raw_mode()?;
        // TODO: implement TUI
        crossterm::terminal::disable_raw_mode()?;
        return Ok(());
    }

    // Ping mode: resolve hosts, check version, spawn ping
    // Resolve each host
    for host in &hosts_or_commands {
        let expanded = expand_cloud_host(host);
        // Try parse as IP first
        if let Ok(ip) = expanded.parse::<IpAddr>() {
            // Check -4/-6 filter
            match (ipv4, ipv6, ip) {
                (true, false, IpAddr::V6(_)) => {
                    return Err(anyhow!("Could not resolve '{}' to IPv4", host));
                }
                (false, true, IpAddr::V4(_)) => {
                    return Err(anyhow!("Could not resolve '{}' to IPv6", host));
                }
                _ => {}
            }
            // IP ok, no DNS needed
            continue;
        }
        // Need DNS lookup
        // Use ToSocketAddrs with port 0
        let addr_str = format!("{}:0", expanded);
        let addrs_result: Result<Vec<_>, _> = addr_str.to_socket_addrs().map(|it| it.collect());
        match addrs_result {
            Ok(addrs) => {
                // Filter by ipv4/ipv6 if requested
                let filtered: Vec<_> = if ipv4 {
                    addrs.into_iter().filter(|a| matches!(a.ip(), IpAddr::V4(_))).collect()
                } else if ipv6 {
                    addrs.into_iter().filter(|a| matches!(a.ip(), IpAddr::V6(_))).collect()
                } else {
                    addrs
                };
                if filtered.is_empty() {
