// Parse ping output line.
// Returns None if line should be ignored (no data point, no t/o).
// Returns Some(Some(duration)) for successful reply (with duration truncated to micros).
// Returns Some(None) for timeout ("no answer yet" at start, case-sensitive, single spaces).
fn parse_ping_line(line: &str) -> Option<Option<Duration>> {
    if line.starts_with("no answer yet") {
        return Some(None);
    }
    if !line.starts_with("64 bytes from") {
        return None;
    }
    // Find time= (case-insensitive) after "64 bytes from"
    // Must be exactly "time=" with no spaces around '=' (case-insensitive for "time")
    // Search for "time=" case-insensitively
    let lower = line.to_lowercase();
    // Find "time=" in lower (which corresponds to same byte positions since ascii)
    // Need to ensure "time=" appears after "64 bytes from" (which is at start, so any "time=" after start is after)
    // Actually line starts with "64 bytes from" (13 chars? "64 bytes from" len 13? Let's just find "time=" anywhere after start)
    let pos = match lower.find("time=") {
        Some(p) => p,
        None => return None,
    };
    // pos is byte index in lower (same as line since ascii lowercasing preserves len for ascii? For non-ascii? Ping lines are ascii, lowercasing preserves len. Good.)
    // Extract after "time=" (5 chars)
    let after = &line[pos + 5..];
    // Parse number: digits + optional '.' + digits (no sign, no exponent, requires integer part, if dot then requires fractional)
    // No leading spaces allowed (after starts immediately with digit? "time= 10.0" has space after '=', fails. Good: after[0] must be digit)
    let bytes = after.as_bytes();
    if bytes.is_empty() || !bytes[0].is_ascii_digit() {
        return None;
    }
    let mut i = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    // Check for '.' + digits?
    if i < bytes.len() && bytes[i] == b'.' {
        // Need at least one digit after '.'
        if i + 1 >= bytes.len() || !bytes[i + 1].is_ascii_digit() {
            return None;
        }
        i += 1; // skip '.'
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }
    let num_str = &after[..i];
    let ms_val: f64 = match num_str.parse::<f64>() {
        Ok(v) => v,
        Err(_) => return None,
    };
    // After number, skip spaces (' ' only, zero or more? "10.0ms" (no space) ok, "10.0 ms" (single space) ok, "10.0  ms" (double space) ok. Tab fails (as observed, tab between number and ms fails). Good: skip ' ' only, not '\t'?)
    let mut j = i;
    while j < bytes.len() && bytes[j] == b' ' {
        j += 1;
    }
    // Check for "ms" case-insensitive prefix (at least "ms", extra after ok? "msec" ok (starts with "ms"), "mss" ok? "m" alone fails. Good: check first 2 chars are 'm','s' case-insensitive)
    if j + 1 >= bytes.len() {
        return None;
    }
    let m = bytes[j] as char;
    let s = bytes[j + 1] as char;
    if !(m.eq_ignore_ascii_case(&'m') && s.eq_ignore_ascii_case(&'s')) {
        return None;
    }
    // Valid time! Convert ms to micros truncated: (ms*1000.0) as u64 micros? For "10.0" ms, 10.0*1000=10000.0, as u64=10000. Good. For "10.1239" ms, 10.1239*1000=10123.9, as u64=10123 (truncates, not rounds). Matches observed truncation (10.1239->10.123). Good.
    // Note: ms_val could be inf? No, since num_str is decimal without exponent, inf impossible. NaN impossible. Negative impossible (no sign). Good.
    let micros = (ms_val * 1000.0) as u64;
    Some(Some(Duration::from_micros(micros)))
