fn run_tui_loop(
    displays: Vec<String>,
    colors: Vec<Color>,
    rx: Receiver<DataPoint>,
    buffer_secs: u64,
    vertical_margin: u16,
    horizontal_margin: u16,
    simple_graphics: bool,
    clear_flag: bool,
    start_instant: Instant,
    start_wall: chrono::DateTime<chrono::Local>,
) -> anyhow::Result<()> {
    use crossterm::event::{self, Event, KeyCode, KeyEventKind, KeyModifiers};
    let n = displays.len();
    let mut states: Vec<TargetState> = displays
        .into_iter()
        .zip(colors.into_iter())
        .map(|(d, c)| TargetState::new(d, c))
        .collect();
    let buffer_f64 = buffer_secs as f64;
    let marker = if simple_graphics { Marker::Dot } else { Marker::Braille };
    let mut stdout = std::io::stdout();
    let backend = CrosstermBackend::new(&mut stdout);
    let mut terminal = Terminal::new(backend)?;
    let _ = terminal.clear();
    let _ = crossterm::execute!(std::io::stdout(), crossterm::cursor::Hide);
    let start_wall_secs = start_wall.timestamp();
    loop {
        while let Ok(dp) = rx.try_recv() {
            if dp.idx >= n { continue; }
            match dp.value {
                None => continue,
                Some(opt_dur) => {
                    states[dp.idx].points.push_back((dp.timestamp, opt_dur));
                    let max_x = dp.timestamp;
                    let cutoff = max_x - buffer_f64;
                    while let Some((x, _)) = states[dp.idx].points.front() {
                        if *x < cutoff { states[dp.idx].points.pop_front(); } else { break; }
                    }
                }
            }
        }
        if event::poll(Duration::from_millis(50)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') if key.modifiers.is_empty() => break,
                        KeyCode::Esc => break,
                        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                        _ => {}
                    }
                }
            }
        }
        let elapsed_f64 = Instant::now().duration_since(start_instant).as_secs_f64();
        let (x_min_f64, x_max_f64) = if elapsed_f64 < buffer_f64 { (0.0, buffer_f64) } else { (elapsed_f64 - buffer_f64, elapsed_f64) };
        let now_wall_secs = chrono::Local::now().timestamp();
        let (x_min_wall_secs, x_max_wall_secs) = if elapsed_f64 < buffer_f64 {
            (start_wall_secs, start_wall_secs + buffer_secs as i64)
        } else {
            (now_wall_secs - buffer_secs as i64, now_wall_secs)
        };
        let fmt_secs = |secs: i64| -> String {
            chrono::DateTime::from_timestamp(secs, 0)
                .map(|dt| {
                    let local: chrono::DateTime<chrono::Local> = dt.into();
                    local.format("%H:%M:%S").to_string()
                })
                .unwrap_or_default()
        };
        let s_min = fmt_secs(x_min_wall_secs);
        let s_max = fmt_secs(x_max_wall_secs);
        let sum = x_min_wall_secs + x_max_wall_secs;
        let s_mid = if sum % 2 != 0 {
            let mid_int = sum.div_euclid(2);
            format!("{}.500", fmt_secs(mid_int))
        } else {
            fmt_secs(sum / 2)
        };
        let x_labels = vec![s_min, s_mid, s_max];
        let mut gmin: Option<u64> = None;
        let mut gmax: Option<u64> = None;
        let mut gn = 0usize;
        for st in &states {
            for (_, opt) in &st.points {
                if let Some(d) = opt {
                    let m = d.as_micros() as u64;
                    gmin = Some(gmin.map_or(m, |v| v.min(m)));
                    gmax = Some(gmax.map_or(m, |v| v.max(m)));
                    gn += 1;
                }
            }
        }
        let (y_min_f64, y_max_f64, y_labels): (f64, f64, Vec<String>) = if gn == 0 {
            (0.0, 1.0, vec!["0ns".to_string(); 7])
        } else {
            let gminv = gmin.unwrap();
            let gmaxv = gmax.unwrap();
            let y_min_micros = gminv * 9 / 10;
            let y_max_init = (gmaxv * 66 + gminv * 9) / 70;
            let width_init = y_max_init.saturating_sub(y_min_micros);
            let width_rounded = (width_init / 6) * 6;
            let y_max_micros = y_min_micros + width_rounded;
            let y_min_f = y_min_micros as f64 / 1_000_000.0;
            let y_max_f = y_max_micros as f64 / 1_000_000.0;
            let step = if width_rounded == 0 { 0 } else { width_rounded / 6 };
            let mut labels = Vec::new();
            for i in 0..7 {
                let v = y_min_micros + (i as u64) * step;
                labels.push(format!("{:?}", Duration::from_micros(v)));
            }
            (y_min_f, y_max_f, labels)
        };
        let mut datasets_data: Vec<Vec<(f64, f64)>> = Vec::new();
        for st in &states {
            let n_succ = st.points.iter().filter(|(_, opt)| opt.is_some()).count();
            let n_timeout = st.points.iter().filter(|(_, opt)| opt.is_none()).count();
            let mut data: Vec<(f64, f64)> = Vec::new();
            if n_succ == 0 {
                if n_timeout == 0 {
                } else {
                    for (x, _) in &st.points {
                        data.push((*x, y_max_f64));
                    }
                }
            } else {
                for (x, opt) in &st.points {
                    match opt {
                        Some(d) => data.push((*x, d.as_secs_f64())),
                        None => data.push((*x, 0.0)),
                    }
                }
            }
            datasets_data.push(data);
        }
        let _ = terminal.draw(|f| {
            let area = f.area();
            let inner = Rect {
                x: area.x.saturating_add(horizontal_margin),
                y: area.y.saturating_add(vertical_margin),
                width: area.width.saturating_sub(horizontal_margin.saturating_mul(2)),
                height: area.height.saturating_sub(vertical_margin.saturating_mul(2)),
            };
            if inner.width == 0 || inner.height == 0 { return; }
            let mut constraints = Vec::new();
            for _ in 0..n { constraints.push(Constraint::Length(1)); }
            constraints.push(Constraint::Min(0));
            let chunks = Layout::default().direction(Direction::Vertical).constraints(constraints).split(inner);
            for (i, st) in states.iter().enumerate() {
                if i >= chunks.len() { break; }
                let chunk = chunks[i];
                if chunk.width == 0 || chunk.height == 0 { continue; }
                let h_constraints = vec![
                    Constraint::Percentage(30),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                ];
                let h_chunks = Layout::default().direction(Direction::Horizontal).constraints(h_constraints).split(chunk);
                let style = Style::default().fg(st.color);
                use ratatui::widgets::Paragraph;
                if !h_chunks.is_empty() {
                    let p = Paragraph::new(st.display.clone()).style(style);
                    f.render_widget(p, h_chunks[0]);
                }
                if let Some((last, min, max, avg, jtr, p95, timeouts)) = st.stats() {
                    let texts = [
                        format!("last {:?}", last),
                        format!("min {:?}", min),
                        format!("max {:?}", max),
                        format!("avg {:?}", avg),
                        format!("jtr {:?}", jtr),
                        format!("p95 {:?}", p95),
                        format!("t/o {}", timeouts),
                    ];
                    for (j, txt) in texts.iter().enumerate() {
                        if j + 1 < h_chunks.len() {
                            let p = Paragraph::new(txt.clone()).style(style);
                            f.render_widget(p, h_chunks[j + 1]);
                        }
                    }
                } else {
                    for j in 0..7 {
                        if j + 1 < h_chunks.len() {
                            let w = h_chunks[j + 1].width as usize;
                            let spaces = " ".repeat(w);
                            let p = Paragraph::new(spaces).style(style);
                            f.render_widget(p, h_chunks[j + 1]);
                        }
                    }
                }
            }
            let chart_idx = n;
            if chart_idx < chunks.len() {
                let chart_area = chunks[chart_idx];
                if chart_area.width == 0 || chart_area.height == 0 { return; }
                let mut datasets = Vec::new();
                for (i, data) in datasets_data.iter().enumerate() {
                    let color = states[i].color;
                    let ds = Dataset::default().marker(marker).graph_type(GraphType::Line).style(Style::default().fg(color)).data(data);
                    datasets.push(ds);
                }
                let x_axis = Axis::default().bounds([x_min_f64, x_max_f64]).labels(x_labels.iter().map(|s| Line::from(s.clone())));
                let y_axis = Axis::default().bounds([y_min_f64, y_max_f64]).labels(y_labels.iter().map(|s| Line::from(s.clone())));
                let chart = Chart::new(datasets).x_axis(x_axis).y_axis(y_axis);
                f.render_widget(chart, chart_area);
            }
        })?;
    }
    let _ = crossterm::execute!(std::io::stdout(), crossterm::cursor::Show);
    let _ = crossterm::terminal::disable_raw_mode();
    if clear_flag {
        let _ = terminal.clear();
    } else {
        if let Ok((cols, rows)) = crossterm::terminal::size() {
            let _ = crossterm::execute!(std::io::stdout(), crossterm::cursor::MoveTo(cols, rows));
        }
    }
    Ok(())
}
